// web/dist/ is generated by scripts/build-wasm.sh and not checked in, so the
// two Emscripten entry points are declared here.
declare module "*/dist/pocket.js" {
  const createModule: import("./pocket.ts").CreatePocketModule;
  export default createModule;
}

declare module "*/dist/pocket-node.js" {
  const createModule: import("./pocket.ts").CreatePocketModule;
  export default createModule;
}
